import {writeFileSync,readFileSync} from 'node:fs';
const runs=[];
for(let index=0;index<5;index++){
 const result=Bun.spawnSync([process.execPath,'test','tests/helpers/test-database.test.ts','src/presentation/cli/commands/export.test.ts','tests/infrastructure/database/repositories/friction-repository.test.ts'],{cwd:process.cwd(),stdout:'pipe',stderr:'pipe',timeout:30000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 runs.push({index:index+1,exit:result.exitCode,output});
 console.log(JSON.stringify({index:index+1,exit:result.exitCode,summary:output.slice(output.lastIndexOf('\n 46 pass'))}));
 if(result.exitCode!==0)break;
}
writeFileSync('.git/b11-repeat.json',JSON.stringify({scope:'Five bounded repeats of current Windows helper/export/friction tests; absence of recurrence is not a root-cause diagnosis.',runs,probeSource:readFileSync('.git/b11-repeat.ts','utf8')},null,2)+'\n');
if(runs.some(x=>x.exit!==0))process.exitCode=1;

