import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {sourceHash,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/';
const read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const hash=(p:string)=>sourceHash(readFileSync(p,'utf8'));
const assert=(v:unknown,m:string)=>{if(!v)throw Error(m);};
const catalog=read(root+'executable-catalog.json'), manifest=read(root+'quality-classifications.json'), ledger=read(root+'work-items.json');
assert(catalog.files.length===448&&!validateInventory(catalog,manifest).length,'Invalid current inventory');
for(const input of [...catalog.files,...catalog.packages])assert(hash(input.path)===input.sourceHash,'Stale catalog source '+input.path);
const packet=read(root+'evidence/B11.1-platform.json'), diagnostic=read(root+'evidence/B11.1-helper-metrics.json'), mutation=read(root+'evidence/B11.1-inode-mutation.json');
for(const input of [...packet.sourceInputs,...diagnostic.sourceInputs,...mutation.sourceInputs])assert(hash(input.path)===input.sourceHash,'Stale evidence '+input.path);
assert(hash('tests/helpers/test-database.test.ts')===mutation.regressionSourceHash,'Stale mutation regression');
const coverage=createCoverageMap(diagnostic.rawCoverage);
for(const row of diagnostic.files){
 const summary=coverage.fileCoverageFor(resolve(row.path)).toSummary().data;
 assert(JSON.stringify(summary)===JSON.stringify(row.metrics),'Diagnostic metrics mismatch '+row.path);
 for(const metric of ['statements','branches','functions','lines'])assert(summary[metric].total>0&&summary[metric].covered===summary[metric].total,'Unexpected helper diagnostic gap');
}
assert(packet.pacedRepeat.runs.length===5&&packet.pacedRepeat.runs.every((r:any)=>r.exit===0&&r.output.includes('51 pass')),'Incomplete bounded repeat proof');
assert(packet.unpacedReproduction.runs.some((r:any)=>r.exit===1)&&packet.unpacedRetryReproduction.runs.some((r:any)=>r.exit===1),'Failed diagnostic history omitted');
assert(mutation.exit===1&&mutation.result.startsWith('KILLED'),'Missing expected mutation failure');
const ids=new Map<string,any>(ledger.items.map((x:any)=>[x.id,x]));
const done=new Set<string>();
function visit(id:string,stack=new Set<string>()){
 assert(ids.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;
 for(const dep of ids.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);
}
assert(ids.size===218&&ids.size===ledger.items.length,'Ledger changed');for(const id of ids.keys())visit(id);
assert(ledger.items.filter((x:any)=>x.status==='active').map((x:any)=>x.id).join()==='B11.1','Wrong active task');
assert(ids.get('B04').status==='blocked'&&ids.get('B05').status==='pending','Premature quality acceptance');
packet.validation={command:'bun .git/b11-platform-validate.ts',exit:0,result:'448 source/two package bindings; current helper/test evidence; raw coverage reconciliation; five bounded repeats and retained failures; acyclic 218-item ledger. B11.1 remains active.',source:readFileSync('.git/b11-platform-validate.ts','utf8')};
packet.checks.push({command:'bun run quality:inventory',exit:0,output:readFileSync('.git/b11-platform-inventory.txt','utf8')});
packet.artifacts=['B11.1-helper-metrics.json','B11.1-inode-mutation.json'].map(name=>({path:root+'evidence/'+name,sourceHash:hash(root+'evidence/'+name)}));
writeFileSync(root+'evidence/B11.1-platform.json',JSON.stringify(packet,null,2)+'\n');
console.log('PASS: current sources, runtime/diagnostic artifacts and dependency ledger reconciled; full quality/review acceptance remains open.');
